        result_summary: None,
        tokens_used: None,
        job_id: None,
        created_at: Utc::now(),
    };

    if let Err(e) = self.store.create_routine_run(&run).await {
        return Err(RoutineError::Database {
            reason: format!("failed to create run record: {e}"),
        });
