```rust
/// Find lightweight runs stuck in 'running' beyond the configured timeout
/// and mark them as failed. Only processes runs with job_id IS NULL
/// (lightweight) to avoid conflicting with sync_dispatched_runs().
async fn sweep_stuck_lightweight_runs(&self) {
    let cutoff = Utc::now() - chrono::Duration::seconds(self.config.lightweight_timeout_secs as i64);
    let runs = match self.store.list_stuck_lightweight_runs(cutoff).await {
        Ok(r) => r,
        Err(e) => {
            tracing::error!("Failed to list stuck lightweight runs: {}", e);
            return;
        }
    };
    if runs.is_empty() { return; }
    tracing::warn!("Sweeping {} stuck lightweight routine runs", runs.len());
    for run in runs {
        // Mark the run as failed
        if let Err(e) = self.store.complete_routine_run(
            run.id, RunStatus::Failed,
            Some("Timed out (stuck run recovery)"), None,
        ).await {
            tracing::error!(run_id = %run.id, "Failed to complete stuck run: {}", e);
            continue;
        }
        // Update the routine's runtime fields
        if let Ok(Some(routine)) = self.store.get_routine(run.routine_id).await {
            let next_fire = if let Trigger::Cron { ref schedule, ref timezone } = routine.trigger {
                next_cron_fire(schedule, timezone.as_deref()).unwrap_or(None)
            } else { None };
            let _ = self.store.update_routine_runtime(
                routine.id, Utc::now(), next_fire,
                routine.run_count + 1, routine.consecutive_failures + 1,
                &routine.state,
            ).await;
        }
    }
}
```

