```rust
pub async fn list_stuck_lightweight_runs(
    &self,
    cutoff: DateTime<Utc>,
) -> Result<Vec<RoutineRun>, DatabaseError> {
    self.inner.list_stuck_lightweight_runs(cutoff).await
