main() {
  local command_name="${1:-}"
  if [[ -z "$command_name" ]]; then
    usage
    exit 1
  fi
  shift || true

  case "$command_name" in
    -h|--help|help)
      usage
      ;;
    init)
      init_env
      ;;
    build)
      build_bins "$@"
      ;;
    build-wasm)
      ensure_env
      build_wasm
      ;;
    install-wasm)
      install_wasm
      ;;
    doctor)
      doctor
      ;;
    # --- PostgreSQL ---
    start-postgres)
      start_postgres
      ;;
    stop-postgres)
      stop_postgres
      ;;
    reset-postgres)
      reset_postgres
      ;;
    # --- TensorZero proxy ---
    start-proxy)
      start_proxy
      ;;
    stop-proxy)
      stop_proxy
      ;;
    # --- XMPP bridge ---
    start-bridge)
      start_bridge
      ;;
    stop-bridge)
      stop_bridge
      ;;
    bridge-status)
      bridge_status
      ;;
    gateway-status)
      gateway_status
      ;;
    bridge-auth-check)
      bridge_auth_check
      ;;
    # --- LunarWing ---
    start-lunarwing)
      start_lunarwing "$@"
      ;;
    stop-lunarwing)
      stop_lunarwing
      ;;
    lunarwing-status)
      lunarwing_status
      ;;
    repl)
      launch_repl "$@"
      ;;
    # --- Orchestration ---
    up)
      stack_up
      ;;
    down)
      stack_down
      ;;
    status)
      status_all
      ;;
    verify)
      verify_stack
      ;;
    # --- Other ---
    smoke)
      smoke
      ;;
    configure-bridge)
      configure_bridge "$@"
      ;;
    rate-limit)
      rate_limit "$@"
      ;;
    render-systemd)
      render_systemd
      ;;
    logs)
      logs "$@"
      ;;
    # --- Multi-tenancy ---
    mt-init)
      mt_init
      ;;
    mt-up)
      mt_up
      ;;
    mt-verify)
      mt_verify
      ;;
    mt-down)
      mt_down
      ;;
    mt-status)
      mt_status
      ;;
    mt-render-systemd)
      mt_render_systemd
      ;;
    mt-tokens)
      mt_tokens
      ;;
    *)
      die "unknown command: $command_name"
      ;;
  esac
}

