1	//! Routine execution engine.
2	//!
3	//! Handles loading routines, checking triggers, enforcing guardrails,
4	//! and executing both lightweight (single LLM call) and full-job routines.
5	//!
6	//! The engine runs two independent loops:
7	//! - A **cron ticker** that polls the DB every N seconds for due cron routines
8	//! - An **event matcher** called synchronously from the agent main loop
9	//!
10	//! Lightweight routines execute inline (single LLM call, no scheduler slot).
11	//! Full-job routines are delegated to the existing `Scheduler`.
12	
13	use std::collections::HashMap;
14	use std::sync::Arc;
15	use std::sync::atomic::{AtomicUsize, Ordering};
16	use std::time::Duration;
17	
18	use chrono::Utc;
19	use regex::Regex;
20	use tokio::sync::{RwLock, mpsc};
21	use uuid::Uuid;
22	
23	use crate::agent::Scheduler;
24	use crate::agent::routine::{
25	    NotifyConfig, Routine, RoutineAction, RoutineRun, RunStatus, Trigger, next_cron_fire,
26	};
27	use crate::channels::{IncomingMessage, OutgoingResponse};
28	use crate::config::RoutineConfig;
29	use crate::context::{JobContext, JobState};
30	use crate::db::Database;
31	use crate::error::RoutineError;
